{
  "window_id": "w0005",
  "observed_failures": [
    {
      "id": "F1",
      "field": "total_amount",
      "filename": "078.jpg",
      "observed": "\"\" (empty string)",
      "evidence": "Delivered predictions row for 078.jpg has total_amount == \"\"; OCR text in a0027 shows 'Grand Total ——— ~\"\"\"92 80' with missing decimal, so extract_total returned None, but writer serialized it as empty string rather than a real null cell. Current xlsx SKILL already warns against exactly this.",
      "contradiction": "candidate xlsx SKILL (Pitfalls: 'Leaving NaN... instead of None') vs. actual output cell"
    },
    {
      "id": "F2",
      "field": "total_amount",
      "filename": "074.jpg",
      "observed": "702.00",
      "evidence": "OCR in a0027 shows both 'Total incl. of GST 102.00' and 'Total Amt Rounded ——S«702.00'. Agent's tier matching picked the LAST generic TOTAL-line in the same tier, hitting the corrupted 'Total Amt Rounded' line. Subtotal/Payment lines both show 102.00; the picked 702.00 is an outlier.",
      "contradiction": "candidate image-ocr SKILL tier semantics (last keyword candidate) vs. multi-candidate reality where corrupted lines must be de-prioritised"
    },
    {
      "id": "F3",
      "field": "total_amount",
      "filename": "077.jpg",
      "observed": "23.26",
      "evidence": "OCR in a0027 shows both 'Total (Inclusive of GST): 23.26' and later 'Rounding Adj: -0.01' then 'TOTAL: 23.25'. Agent matched the 'Inclusive of GST' line and ignored the post-rounding 'TOTAL:' line. The final paid total after rounding adjustment is the printed grand total.",
      "contradiction": "candidate image-ocr SKILL keyword priority (TOTAL AMOUNT tier > bare TOTAL) vs. task reality that the rounded/final 'TOTAL:' line is the ground-truth total"
    },
    {
      "id": "F4",
      "field": "date",
      "filename": "034.jpg",
      "observed": "2018-08-09",
      "evidence": "Multi-pass OCR yielded both '09/03/2018' (preprocessed PSM 6, a0027) and '09/08/2018' (default PSM, a0029). Agent's 'first non-null from variants' rule took the default-OCR date; feedback marks it incorrect. The skill offers no cross-variant consensus or digit-confusion handling for 0/8/3.",
      "contradiction": "image-ocr SKILL date extraction (first-match wins) vs. multiple OCR variants disagreeing on a single digit"
    },
    {
      "id": "F5",
      "field": "run",
      "filename": null,
      "observed": "termination_reason=max_iterations at 65",
      "evidence": "execution_metadata.termination_reason='max_iterations'; agent kept iterating on edge cases instead of converging. Related_records show repeated OCR dumps and incremental regex tweaks without a planned budget or a stop criterion after an acceptable sweep.",
      "contradiction": "no SKILL currently defines a per-run iteration/evaluation budget or a 'stop after full-batch pass with N unresolved' heuristic"
    }
  ],
  "root_causes": [
    {
      "id": "RC1",
      "summary": "image-ocr priority/exclusion scheme lacks a top tier for post-rounding final totals (`TOTAL ROUNDED`, `TOTAL AMT ROUNDED`, `TOTAL AFTER ROUNDING`, `ROUNDED TOTAL`) and no concept of 'line printed AFTER a Rounding Adj line is the final total'.",
      "supports": ["F3", "F2"]
    },
    {
      "id": "RC2",
      "summary": "Within a tier the skill defines only a fallback 'last number on next line'; it has no guidance for choosing between multiple same-tier matches. Agent's heuristic (last candidate) is brittle when OCR corruption appears later in the receipt.",
      "supports": ["F2", "F3"]
    },
    {
      "id": "RC3",
      "summary": "Multi-pass OCR is described, but the skill gives no consensus/agreement policy across variants for either dates or totals — agent took the first non-null, so a single-digit OCR error wins over plausibility and cross-variant agreement.",
      "supports": ["F4", "F2"]
    },
    {
      "id": "RC4",
      "summary": "xlsx SKILL already enumerates the real-null rule, but its code example does not show the end-to-end writer explicitly replacing missing fields with `None` before `to_excel`; it also does not require a round-trip re-read assertion that non-null totals match `^\\d+\\.\\d{2}$` and that nulls are empty cells, not empty strings. The agent's writer emitted `\"\"`.",
      "supports": ["F1"]
    },
    {
      "id": "RC5",
      "summary": "No skill encodes a run-level loop budget or a convergence criterion (e.g., 'run full batch, record disagreements, make at most K targeted fixes, then stop'). Agent oscillated on individual receipts past the iteration cap.",
      "supports": ["F5"]
    },
    {
      "id": "RC6",
      "summary": "image-ocr strict `\\d+\\.\\d{2}` number rule, while helping precision (F fixed 064 in the source run), silently drops totals when OCR loses the decimal (e.g., '1000' for 10.00, '92 80' for 92.80). Skill does not describe a safe recovery (keyword-anchored line with space-separated 'NN NN' pattern → 'NN.NN') limited to known total lines.",
      "supports": ["F1"]
    }
  ],
  "skill_defects": [
    {
      "skill": "image-ocr",
      "defect": "TOTAL_PRIORITY tiers omit post-rounding final-total patterns (`TOTAL\\s*ROUNDED`, `TOTAL\\s*AMT\\s*ROUNDED`, `TOTAL\\s*AFTER\\s*ROUNDING`, `ROUNDED\\s*TOTAL`, `NET\\s*TOTAL` already present) and omit a rule that prefers a `TOTAL`-line appearing AFTER a `ROUNDING ADJ` line in the same block."
    },
    {
      "skill": "image-ocr",
      "defect": "Within-tier selection policy is unspecified; code takes first-matching tier and `last_number` of first-matching line. No guidance for: (a) iterating all same-tier candidates, (b) scoring by line cleanliness (fraction of alnum chars that are digits/currency), (c) cross-checking against subtotal/payment/cash values for consistency."
    },
    {
      "skill": "image-ocr",
      "defect": "Multi-pass OCR example lacks a consensus rule. There is no documented way to combine candidates from several passes (e.g., agreement voting, prefer value that also appears on a subtotal/payment line, prefer the higher-priority tier across all passes)."
    },
    {
      "skill": "image-ocr",
      "defect": "Date extraction accepts the earliest valid match from a single text; no cross-variant agreement, no sanity validation against receipt context (year range, month<=12), and no documented policy for ambiguous `03` vs `08` vs `09` digit confusions."
    },
    {
      "skill": "image-ocr",
      "defect": "Strict 2-decimal NUM_RE is correct for precision but the skill does not document a keyword-anchored recovery for OCR-lost decimals ('1000' → '10.00', 'NN NN' with a space → 'NN.NN') limited to lines already matched by a priority keyword."
    },
    {
      "skill": "xlsx",
      "defect": "Strict-schema canonical example does not explicitly coerce missing fields to Python `None` before `to_excel` and does not mandate a writer-side check that no cell contains `\"\"`, `\"None\"`, `\"NaN\"`, or `\"nan\"`. The round-trip assertion should also verify that `pd.isna(cell)` is true for failed extractions."
    },
    {
      "skill": "xlsx",
      "defect": "No guidance on a small batch-level validation summary (counts of null vs. populated per column, histogram of decimal precision for monetary strings) that the agent could use as a stop/continue signal."
    },
    {
      "skill": "openai-vision",
      "defect": "No cross-reference from image-ocr: when Tesseract multi-pass disagrees on a single digit in dates/totals, this skill is the natural tie-breaker but it is not mentioned as a fallback in image-ocr's Quality Self-Check or in a receipt-oriented section here."
    },
    {
      "skill": "image-ocr",
      "defect": "No run-level budget/convergence note. A receipt-pipeline section should state: do one full batch, collect per-receipt confidences, then perform at most K targeted re-extractions and stop regardless."
    }
  ],
  "repair_recommendations": [
    {
      "target": "image-ocr",
      "change": "Add a new TOP priority tier for post-rounding final totals: patterns `TOTAL\\s*ROUNDED`, `TOTAL\\s*AMT\\s*ROUNDED`, `TOTAL\\s*AFTER\\s*ROUNDING`, `ROUNDED\\s*TOTAL`. Within a receipt, if a `ROUNDING ADJ(USTMENT)?` line is detected, the first `TOTAL`/`GRAND TOTAL` line appearing AFTER it (within ~3 lines) outranks any earlier `TOTAL (Inclusive of GST)` line. Keep existing exclusions.",
      "generality": "Applies to any receipt pipeline where grand totals are reprinted after a rounding adjustment."
    },
    {
      "target": "image-ocr",
      "change": "Specify within-tier selection: iterate all same-tier candidate lines, compute a cleanliness score (ratio of 'expected' chars to garbage like `—`, `«`, `¥`, `|`), and prefer the highest-scoring line; break ties by consistency with other value lines (subtotal/payment/cash). Document and provide a small helper in-skill."
    },
    {
      "target": "image-ocr",
      "change": "Add a Multi-Pass Consensus subsection: run N configured passes (default + preprocessed + optional PSM 11), extract candidates from each as (tier, value, cleanliness), and select by: (1) lowest tier index, (2) highest cross-pass agreement count, (3) highest cleanliness, (4) stable order. Replace the current 'first non-null wins' example."
    },
    {
      "target": "image-ocr",
      "change": "Extend date extraction: run DATE_PATTERNS over every OCR variant, build a (date, votes) tally, and pick the highest-vote valid date; discard dates with month>12 or day>31; when votes tie, prefer the variant that also produced the chosen total. Return `None` only if no variant yields a valid date."
    },
    {
      "target": "image-ocr",
      "change": "Add a bounded OCR-decimal-recovery rule, scoped to lines already matched by a priority keyword and already screened by exclusions: if no 2-decimal number is present but a `(\\d+)\\s(\\d{2})\\b` or `\\b(\\d{2,5})\\b` appears, interpret as `NN.NN` (space collapse) or `X.YY` (last 2 digits as cents) respectively, and emit it only if it is within ±1% of another value on a Subtotal/Payment/Cash line in the same receipt."
    },
    {
      "target": "image-ocr",
      "change": "Add a Receipt Batch Pipeline section with an explicit convergence budget: 1 full sweep, collect per-field nulls and low-confidence fields, perform at most K (e.g., 3) targeted re-extractions per receipt, then stop. State that iteration-cap termination is a bug, not success."
    },
    {
      "target": "xlsx",
      "change": "Harden the strict-schema canonical pattern: before `to_excel`, apply `df = df.where(df.notna(), None)` and assert no cell equals `\"\"`, `\"None\"`, `\"NaN\"`, `\"nan\"`; after `to_excel`, re-read with `pd.read_excel` and assert `pd.isna` for every intended-null cell and `re.fullmatch(r'\\d+\\.\\d{2}', v)` for every non-null monetary string."
    },
    {
      "target": "xlsx",
      "change": "Add a small 'batch-level sanity report' recipe: null count per column, decimal-precision histogram for monetary strings, filename-order check, header exact-match check. Recommend logging the report so the agent uses it as a stop signal."
    },
    {
      "target": "openai-vision",
      "change": "Add a short 'Receipt field tie-breaker' subsection: when Tesseract multi-pass disagrees on a single digit of a date or total, call GPT-4o vision with a strict prompt that returns ONLY the two disputed fields as JSON for that receipt; use the returned value only if it matches one of the already-generated candidates. Cross-link from image-ocr's Quality Self-Check."
    },
    {
      "target": "openai-vision",
      "change": "Document that this fallback must be rate-limited and budgeted (e.g., at most one call per receipt flagged as ambiguous) to avoid runaway iterations."
    },
    {
      "target": "xlsx",
      "change": "Explicitly state that for extraction tasks the spreadsheet must not contain formulas; the 'Use Formulas, Not Hardcoded Values' guidance applies only to financial models and must not be followed for strict-schema outputs. The current draft hints at this but should state it as a hard rule."
    }
  ],
  "confidence": {
    "overall": 0.78,
    "per_failure": {
      "F1": 0.95,
      "F2": 0.9,
      "F3": 0.85,
      "F4": 0.6,
      "F5": 0.9
    },
    "notes": "F1/F2/F3/F5 are directly supported by the delivered prediction cells, OCR dumps in a0027/a0029, and execution_metadata. F4 is lower because the oracle date is not accessible — the feedback only confirms 'date_correct=false' for 034.jpg, so the specific corrective digit is inferred from the two OCR variants seen, not from an oracle value."
  }
}
